const feeds = $('Unir feeds final').all().map(i => i.json);
const known = new Set($('Noticias ya publicadas').all().map(i => i.json && i.json.source_url).filter(Boolean));
const weekAgo = Date.now() - 7 * 24 * 3600 * 1000;
const clean = (s) => String(s || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim().slice(0, 300);
const hostOf = (u) => {
  const m = String(u || '').match(/^https?:\/\/([^\/]+)/i);
  return m ? m[1].replace(/^www\./i, '') : 'unknown';
};
const seen = new Set();
const raw = [];
for (const f of feeds) {
  const url = f.link || f.guid || '';
  if (!url || known.has(url) || seen.has(url)) continue;
  const when = Date.parse(f.isoDate || f.pubDate || '') || Date.now();
  if (when < weekAgo) continue;
  seen.add(url);
  raw.push({ title: clean(f.title).slice(0,200), summary: clean(f.contentSnippet || f.content), source_url: url, source: hostOf(url), published: new Date(when).toISOString().slice(0,10), ts: when });
}
raw.sort((a,b) => b.ts - a.ts);
const perSourceCap = 3;
const counts = {};
const capped = [];
for (const c of raw) {
  counts[c.source] = (counts[c.source] || 0) + 1;
  if (counts[c.source] > perSourceCap) continue;
  capped.push(c);
}
const top = capped.slice(0, 10).map(function(c) { const r = {}; for (const k in c) { if (k !== 'ts') r[k] = c[k]; } return r; });
return [{ json: { count: top.length, candidates: top } }];

