const newsItems = clean($('Noticias del sitio').all()).map(j => ({
  id: j.id, title: j.title, summary: j.summary || '', url: j.url || '/news/',
  source_url: j.source_url || null, image: j.image_url || null, lang: j.lang || site.default_lang,
