const now = new Date().toISOString();
const newsFile = JSON.stringify({ site: site.slug, generated_at: now, items: newsItems }, null, 2);
const hashable = JSON.stringify({ n: newsItems });
let h = 0x811c9dc5;
for (let i = 0; i < hashable.length; i++) { h ^= hashable.charCodeAt(i); h = (h * 0x01000193) >>> 0; }
const contentHash = h.toString(16);
const metaFile = JSON.stringify({ site: site.slug, generated_at: now, version: Date.now() }, null, 2);
return [{ json: {
  site_id: site.id, site_slug: site.slug, site_name: site.name, site_domain: site.domain, repo: site.repo,
