const raw = $json.candidates || [];
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const truncate = (s, max) => {
  s = String(s || '');
  return s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s;
};
const candidates = raw.map(c => ({ title: c.title, summary: c.summary, source_url: c.source_url, site_slug: c.site_slug || 'breachfolio', lang: c.lang || 'en' }));
const lines = raw.map((c, i) => {
  const n = i + 1;
  return n + '. ' + esc(truncate(c.title, 90)) + '\n' + esc(truncate(c.summary || '', 110)) + '\n' + esc(c.source_url);
});
let text = '📰 Recap Breachfolio — ' + raw.length + ' candidatas\n\n' +
  lines.join('\n\n') +
  '\n\nPulsa los numeros que quieras publicar, maximo 5 (pulsar el mismo dos veces NO lo duplica).\n' +
  'Luego pulsa ✅ Publicar seleccionadas.\n' +
  '🔄 Limpiar -> vacia tu seleccion\n' +
  '👎 No publicar nada -> descarta el dia\n\n' +
  'Nada se publica hasta que pulses Publicar. Las no elegidas no se guardan y pueden volver a salir manana.';
if (text.length > 4096) text = text.slice(0, 4090).trimEnd() + '\n…';
return [{ json: { count: raw.length, candidates, text } }];

const prep = $('Preparar accion (Telegram)').first().json;
const poolRow = $('Cargar última pool (Data Table)').first().json;
let candidates = [];
try { candidates = JSON.parse(poolRow.candidates || '[]'); } catch (e) { candidates = []; }
const count = candidates.length;

// El registro de selecciones (una fila por pulsacion) es la fuente de verdad.
// Deduplicar aqui hace imposible que una noticia entre dos veces, y como cada
// pulsacion INSERTA su propia fila, dos pulsaciones seguidas no se pisan.
const rows = $input.all().map((i) => i.json).filter((r) => r && Number.isInteger(r.idx));
const norm = (arr) => [...new Set(arr.filter((n) => Number.isInteger(n) && n >= 1 && n <= count))].sort((a, b) => a - b);
const selected = norm(rows.map((r) => r.idx));
const label = (arr) => (arr.length ? arr.join(', ') : 'ninguna');

const data = prep.data;
let action = 'fin';
let toast = '';
let newResolved = prep.resolved === true;
let newSelected = selected;
let chosen = [];

if (prep.resolved) {
  toast = 'El recap de esta semana ya se resolvio.';
} else if (/^recap_pick_\d+$/.test(data)) {
  toast = prep.isPick ? 'Seleccionadas: ' + label(selected) : 'Esa opcion no existe.';
} else if (data === 'recap_clear') {
  toast = 'Seleccion vaciada.';
} else if (data === 'recap_publish') {
  if (selected.length === 0) {
    toast = 'No has seleccionado ninguna noticia.';
  } else {
    action = 'publicar';
    newResolved = true;
    chosen = selected.map((n) => candidates[n - 1]).filter(Boolean);
    toast = 'Publicando ' + chosen.length + ' noticia(s)...';
  }
} else if (data === 'recap_all') {
  // Boton retirado (tope de 5 lo contradecia) - mensajes antiguos con este
  // boton pueden seguir en el chat; se responde sin publicar nada.
  toast = 'Boton "Todas" retirado - selecciona hasta 5 con los numeros y pulsa Publicar.';
} else if (data === 'recap_none') {
  action = 'nada';
  newResolved = true;
  toast = 'Entendido, no se publica nada.';
} else {
  toast = 'Esa opcion no existe.';
}

return [{ json: {
  action,
  toast: String(toast).slice(0, 200),
  poolId: prep.poolId,
  newSelected: JSON.stringify(newSelected),
  newResolved,
  chosen,
  queryId: prep.queryId,
  count
} }];

const chosen = $('Router selección (Telegram)').first().json.chosen || [];
return chosen.map((c) => ({ json: {
  site_slug: c.site_slug || 'breachfolio',
  lang: c.lang || 'en',
  title: c.title || '',
  summary: c.summary || '',
  url: c.url || '/news/',
  source_url: c.source_url || '',
  image_url: c.image_url || ''
} }));

