const cb = trig.callback_query || {};
const data = cb.data ? String(cb.data) : '';
const queryId = cb.id || '';

const row = $json || {};
const poolId = row.id;
const resolved = row.resolved === true;
let candidates = [];
try { candidates = JSON.parse(row.candidates || '[]'); } catch (e) { candidates = []; }
const count = candidates.length;

const m = data.match(/^recap_pick_(\d+)$/);
const idx = m ? parseInt(m[1], 10) : 0;

// Solo insertamos/borramos si la semana no esta resuelta
const isPick = !resolved && !!m && idx >= 1 && idx <= count;
const isClear = !resolved && data === 'recap_clear';

return [{ json: { poolId, resolved, count, data, queryId, idx, isPick, isClear } }];

const rows = $input.all().map(i => i.json);
